using CustomCodeFramework.Postgres.EntityFramework.Configurations;using Dhole.Content.Domain.Navigation.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Dhole.Content.Persistence.Configurations.Navigation;internal sealed class NavigationMenuConfiguration:EntityTypeConfigurationBase<NavigationMenu,Guid>{public override void Configure(EntityTypeBuilder<NavigationMenu>b){base.Configure(b);b.ToTable("navigation_menus");b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.SiteKey).HasMaxLength(80).IsRequired();b.Property(x=>x.Name).HasMaxLength(200).IsRequired();b.Property(x=>x.Location).HasMaxLength(100).IsRequired();b.HasIndex(x=>new{x.SiteKey,x.Location}).IsUnique().HasFilter("is_deleted = false");b.HasMany(x=>x.Items).WithOne(x=>x.Menu).HasForeignKey(x=>x.MenuId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Items).UsePropertyAccessMode(PropertyAccessMode.Field);}}
